/* BookShelf - Shelves, list and stats views: filtering and rendering. */
"use strict";
/* ---------- filtering ---------- */
function matches(b){
  if(fShelf&&b.shelf!==fShelf)return false;
  if(fTag&&!(b.tags||[]).includes(fTag))return false;
  if(fStatus==='check'){if(!b.check)return false}
  else if(fStatus==='rated'){if(!b.rating)return false}
  else if(fStatus&&b.status!==fStatus)return false;
  if(q){const n=norm(q);if(!norm(`${b.title} ${b.author} ${b.notes} ${b.person} ${b.review} ${(b.tags||[]).join(' ')}`).includes(n))return false}
  return true;
}

/* ---------- render ---------- */
function render(){
  if(!memMode&&!(loaded.books&&loaded.meta))return;
  document.querySelectorAll('.tabs button').forEach(b=>b.classList.toggle('on',b.dataset.v===view));
  $('fShelf').innerHTML='<option value="">כל המדפים</option>'+meta.shelves.map((s,i)=>`<option value="${s.id}"${s.id===fShelf?' selected':''}>מדף ${i+1}</option>`).join('');
  if(introShown)$('main').classList.remove('intro');
  const sy=window.scrollY;
  let html='';
  if(view==='stats')html=renderStats();
  else if(view==='reading')html=renderReading();
  else{
    html+=renderChips();
    const list=books.filter(matches);
    const plain=!fStatus&&!q&&!fShelf&&!fTag&&!arrange;
    if(plain){
      const reading=books.filter(b=>b.status==='reading');
      const out=books.filter(b=>b.status==='borrowed'||b.status==='lent').sort((a,b)=>(a.due||'9').localeCompare(b.due||'9'));
      if(reading.length)html+=`<div class="section-title">בקריאה עכשיו</div><div class="cards">${reading.map(card).join('')}</div>`;
      if(out.length)html+=`<div class="section-title">השאלות ומה שצריך להחזיר</div><div class="cards">${out.map(card).join('')}</div>`;
      const chk=books.filter(b=>b.check).length;
      if(chk&&canWrite)html+=`<div class="note edit-only"><span>${chk} ספרים זוהו מהתמונות בחוסר ודאות (נקודה כתומה בראש השדרה). כדאי לעבור עליהם ולתקן.</span><button data-f="check">הצג אותם</button></div>`;
    }
    if(view==='shelves'){
      if(arrange)html+=`<div class="note dock"><span>${moving?'עכשיו לחץ על ספר כדי להניח לפניו את הספר שבחרת, או על "לסוף המדף".':'מצב סידור: לחץ על ספר כדי להזיז אותו. ליד כל מדף יש חצים להזזת המדף וכפתורי מיון.'}</span><button class="primary" id="arrDone">סיום סידור</button></div>`;
      const shelfBooks=list.filter(b=>b.status!=='want');
      if(fStatus!=='want'&&(shelfBooks.length||arrange)){
        const N=meta.shelves.length;
        const groups=meta.shelves.map((s,i)=>({s,i,b:shelfBooks.filter(x=>x.shelf===s.id).sort((a,b)=>a.pos-b.pos)}));
        const orphan=shelfBooks.filter(x=>shelfIdx(x.shelf)<0);
        if(orphan.length)groups.push({s:{id:''},i:-1,b:orphan});
        html+='<div class="cabinet">'+groups.filter(g=>g.b.length||arrange).map(g=>`<section class="shelf"><div class="shead"><span class="plaque">${g.i<0?'ללא מדף':'מדף '+(g.i+1)} <small>${g.b.length} ספרים</small></span>${arrange&&g.i>=0?`<button data-sh="${g.i}" data-d="-1"${g.i===0?' disabled':''} aria-label="העלאת המדף">▲</button><button data-sh="${g.i}" data-d="1"${g.i===N-1?' disabled':''} aria-label="הורדת המדף">▼</button><button data-sort="${g.s.id}" data-k="author">מיון לפי סופר</button><button data-sort="${g.s.id}" data-k="title">לפי שם</button>`:''}</div><div class="rack">${g.b.map((b,i)=>spine(b,i)).join('')}${arrange&&g.i>=0?`<button class="slot${moving?' live':''}" data-end="${g.s.id}">לסוף המדף</button>`:''}${!g.b.length&&!arrange?'':''}</div><div class="board"></div></section>`).join('')+'</div><div class="cabinet-feet"><i></i><i></i></div>';
      }
      const wants=list.filter(b=>b.status==='want');
      if(wants.length&&!arrange)html+=`<div class="section-title">רוצה לקרוא</div><div class="cards">${wants.map(card).join('')}</div>`;
      if(!shelfBooks.length&&!wants.length&&!arrange)html+=books.length?'<div class="empty">לא נמצאו ספרים</div>':'<div class="empty">הארון ריק. אפשר להתחיל ב"הוספה".</div>';
    }else html+=renderTable(list);
  }
  $('main').innerHTML=html;
  window.scrollTo(0,sy);
}
function renderReading(){
  const search=norm(q);
  const reading=books.filter(b=>b.status==='reading'&&(!search||norm(`${b.title} ${b.author} ${b.notes} ${b.review}`).includes(search)));
  if(!reading.length)return `<section class="reading-view" aria-labelledby="readingTitle"><div class="reading-heading"><div><h2 id="readingTitle">פינת הקריאה שלי</h2><p>${search?'לא נמצאו ספרים בקריאה התואמים לחיפוש.':'אין כרגע ספרים בקריאה.'}</p></div></div>${search?'':'<button class="primary edit-only" data-pick-reading>לבחור ספר לקריאה</button>'}</section>`;
  const cards=reading.map(b=>{
    const page=Math.max(0,+b.page||0),pages=Math.max(0,+b.pages||0),pct=pages?Math.min(100,Math.round(100*page/pages)):0;
    const cover=b.front?`<img src="${coverUrl(b.front)}" alt="">`:'';
    return `<article class="reading-card">
      <button class="reading-book" data-id="${esc(b.id)}" aria-label="פתיחת פרטי הספר ${esc(b.title)}">
        <span class="reading-cover">${cover}</span><span class="reading-info"><strong>${esc(b.title)}</strong><span>${esc(b.author)}</span></span>
      </button>
      <div class="reading-progress">
        ${pages?`<div class="bar" role="progressbar" aria-label="התקדמות בקריאת ${esc(b.title)}" aria-valuemin="0" aria-valuemax="${pages}" aria-valuenow="${Math.min(page,pages)}"><div style="width:${pct}%"></div></div><span>${page} מתוך ${pages} עמודים · ${pct}%</span>`:`<span>${page?`עמוד ${page}`:'ההתקדמות עוד לא עודכנה'}${b.started?` · התחלה ${fmtDate(b.started)}`:''}</span>`}
      </div>
      <div class="reading-actions edit-only">
        <button data-reading-step="-1" data-id="${esc(b.id)}" aria-label="עמוד קודם: ${esc(b.title)}"${page<=0?' disabled':''}>−</button>
        <span>עמוד ${page}</span>
        <button data-reading-step="1" data-id="${esc(b.id)}" aria-label="עמוד הבא: ${esc(b.title)}"${pages&&page>=pages?' disabled':''}>+</button>
      </div>
      <div class="reading-footer">
        ${canWrite?`<button class="primary" data-reading-finish="${esc(b.id)}">סיימתי לקרוא</button>`:''}
        <button data-id="${esc(b.id)}">פרטי הספר</button>
      </div>
    </article>`;
  }).join('');
  return `<section class="reading-view" aria-labelledby="readingTitle"><div class="reading-heading"><div><h2 id="readingTitle">פינת הקריאה שלי</h2><p>${reading.length===1?'ספר אחד בקריאה':`${reading.length} ספרים בקריאה`}</p></div></div><div class="reading-grid">${cards}</div></section>`;
}
function renderChips(){
  const cnt=k=>books.filter(b=>b.status===k).length;
  const rated=books.filter(b=>b.rating),avg=rated.length?(rated.reduce((a,b)=>a+b.rating,0)/rated.length).toFixed(1):null;
  const chk=books.filter(b=>b.check).length;
  let h=`<div class="chips"><div class="chip${!fStatus?' on':''}" data-f=""><b>${books.filter(b=>b.status!=='want').length}</b> ספרים בארון</div>`;
  for(const k in ST){const n=cnt(k);if(n||k==='reading'||k==='read')h+=`<div class="chip${fStatus===k?' on':''}" data-f="${k}"><i style="background:${ST[k].c}"></i><b>${n}</b> ${ST[k].l}</div>`}
  if(rated.length)h+=`<div class="chip${fStatus==='rated'?' on':''}" data-f="rated"><span class="stars-s">★</span><b>${avg}</b> ממוצע (${rated.length})</div>`;
  if(chk)h+=`<div class="chip edit-only${fStatus==='check'?' on':''}" data-f="check"><i style="background:var(--warn)"></i><b>${chk}</b> לבדיקה</div>`;
  h+='</div>';
  const tags={};books.forEach(b=>(b.tags||[]).forEach(t=>tags[t]=(tags[t]||0)+1));
  const tk=Object.keys(tags).sort((a,b)=>tags[b]-tags[a]);
  if(tk.length)h+=`<div class="chips">${tk.map(t=>`<span class="tagchip${fTag===t?' on':''}" data-tag="${esc(t)}">${esc(t)} ${tags[t]}</span>`).join('')}</div>`;
  return h;
}
function renderTable(list){
  if(!list.length)return '<div class="empty">לא נמצאו ספרים</div>';
  const cols=[['title','שם הספר'],['author','סופר/ת'],['status','סטטוס'],['rating','דירוג'],['shelf','מדף']];
  const val=(b,k)=>k==='shelf'?(b.status==='want'?'ת':String(shelfIdx(b.shelf)+100)):k==='status'?ST[b.status].l:k==='rating'?String(9-b.rating):b[k]||'';
  const sorted=[...list].sort((a,b)=>val(a,sortKey).localeCompare(val(b,sortKey),'he')*sortDir||a.title.localeCompare(b.title,'he'));
  return `<table><thead><tr>${cols.map(([k,l])=>`<th data-col="${k}"${k==='shelf'?' class="hide-sm"':''}>${l}${sortKey===k?(sortDir>0?' ▴':' ▾'):''}</th>`).join('')}</tr></thead><tbody>${sorted.map(b=>`<tr class="row" data-id="${b.id}"><td>${esc(b.title)} ${b.check?'<span class="tag chk">לבדיקה</span>':''}</td><td>${esc(b.author)}</td><td><span class="tag" style="background:${ST[b.status].c}">${ST[b.status].l}</span>${b.person?' <small>'+esc(b.person)+'</small>':''}</td><td class="stars-s">${starsTxt(b.rating)}</td><td class="hide-sm">${b.status==='want'?'':esc(shelfName(b.shelf))}</td></tr>`).join('')}</tbody></table>`;
}
function card(b){
  let extra='';
  if(b.status==='reading'){const p=b.pages?Math.min(100,Math.round(100*(b.page||0)/b.pages)):0;extra=b.pages?`<div class="bar"><div style="width:${p}%"></div></div><div class="a">עמוד ${b.page||0} מתוך ${b.pages} (${p}%)</div>`:`<div class="a">${b.started?'התחלתי ב-'+fmtDate(b.started):'לחץ לעדכון התקדמות'}</div>`}
  else if(b.status==='want'){extra=b.notes?`<div class="a">${esc(b.notes)}</div>`:''}
  else{extra=`<div class="a"><span class="tag" style="background:${ST[b.status].c}">${ST[b.status].l}</span> ${esc(b.person||'')}</div>${b.due?`<div class="${overdue(b)?'alert':'a'}">${overdue(b)?'באיחור - ':''}להחזרה עד ${fmtDate(b.due)}</div>`:''}`}
  return `<div class="card" data-id="${b.id}"><div class="mini" style="background-color:${colorOf(b)}${b.front?`;background-image:url('${coverUrl(b.front)}')`:''}"></div><div style="min-width:0;flex:1"><div class="t">${esc(b.title)}</div><div class="a">${esc(b.author)}</div>${extra}</div></div>`;
}
function spine(b,i){
  const c=colorOf(b),h=180+hash(b.title)%70,w=34+hash(b.author+b.title)%12;
  return `<button class="spine${LIGHT.has(c)?' light':''}${b.status==='given'?' ghost':''}${b.status==='reading'&&!arrange?' reading':''}${moving===b.id?' sel':''}" style="background-color:${c};height:${h}px;width:${w}px;--i:${i||0}" data-id="${b.id}" title="${esc(b.title)} - ${esc(b.author)} (${ST[b.status].l})"><b>${esc(b.title)}</b><span>${esc(b.author)}</span>${b.status!=='shelf'?`<i class="rib" style="background:${ST[b.status].c}"></i>`:''}${b.rating?`<i class="st">${starsTxt(b.rating)}</i>`:''}${b.check?'<i class="flag"></i>':''}</button>`;
}

/* ---------- stats ---------- */
function renderStats(){
  const owned=books.filter(b=>b.status!=='want');
  const read=books.filter(b=>b.status==='read');
  const yr=new Date().getFullYear();
  const readYear=read.filter(b=>(b.finished||'').startsWith(yr+'')).length;
  const rated=books.filter(b=>b.rating);
  const avg=rated.length?(rated.reduce((a,b)=>a+b.rating,0)/rated.length).toFixed(1):'-';
  let h=`<div class="kpis"><div class="kpi"><b>${owned.length}</b><span>ספרים בארון</span></div><div class="kpi"><b>${read.length}</b><span>קראתי</span></div><div class="kpi"><b>${books.filter(b=>b.status==='reading').length}</b><span>בקריאה עכשיו</span></div><div class="kpi"><b>${avg}</b><span>דירוג ממוצע (${rated.length} ספרים)</span></div></div>`;
  const goal=meta.goal||0,pct=goal?Math.min(100,Math.round(100*readYear/goal)):0;
  h+=`<div class="panel"><h3>יעד קריאה ל-${yr}</h3><div class="sub">${goal?`קראת ${readYear} מתוך ${goal} ספרים (${pct}%)`:'עוד לא הוגדר יעד. כמה ספרים תרצה לקרוא השנה?'}</div><div class="goal"><div class="bar"><div style="width:${pct}%"></div></div><label class="edit-only">יעד: <input type="number" min="0" id="goalIn" value="${goal||''}"></label></div></div>`;
  // finished per month, last 12 months
  const now=new Date(),months=[];
  for(let i=11;i>=0;i--){const d=new Date(now.getFullYear(),now.getMonth()-i,1);months.push({k:d.getFullYear()+'-'+String(d.getMonth()+1).padStart(2,'0'),l:MONTHS[d.getMonth()]})}
  months.forEach(m=>m.n=read.filter(b=>(b.finished||'').startsWith(m.k)).length);
  const mx=Math.max(1,...months.map(m=>m.n));
  h+=`<div class="grid2"><div class="panel"><h3>ספרים שסיימתי בכל חודש</h3><div class="sub">12 החודשים האחרונים, לפי תאריך הסיום</div><div class="vbars">${months.map(m=>`<div class="c" title="${m.l}: ${m.n} ספרים">${m.n?`<em>${m.n}</em>`:''}<i style="height:${m.n/mx*100}%"></i></div>`).join('')}</div><div class="vlabels">${months.map(m=>`<span>${m.l}</span>`).join('')}</div></div>`;
  const rd=[5,4,3,2,1].map(n=>({l:starsTxt(n),n:rated.filter(b=>b.rating===n).length}));
  h+=`<div class="panel"><h3>איך דירגתי</h3><div class="sub">מספר הספרים בכל דירוג</div>${hbars(rd,'stars-s')}</div>`;
  const au={};owned.forEach(b=>{if(b.author&&b.author!=='לא מזוהה')au[b.author]=(au[b.author]||0)+1});
  const top=Object.entries(au).sort((a,b)=>b[1]-a[1]).slice(0,8).map(([l,n])=>({l,n}));
  h+=`<div class="panel"><h3>הסופרים הנפוצים בארון</h3><div class="sub">לפי מספר הספרים</div>${hbars(top)}</div>`;
  const sd=Object.keys(ST).map(k=>({l:ST[k].l,n:books.filter(b=>b.status===k).length})).filter(x=>x.n);
  h+=`<div class="panel"><h3>מצב הספרים</h3><div class="sub">כל הספרים, כולל רשימת "רוצה לקרוא"</div>${hbars(sd)}</div></div>`;
  return h;
}
function hbars(rows,lc){const mx=Math.max(1,...rows.map(r=>r.n));return rows.map(r=>`<div class="hbar" title="${esc(r.l)}: ${r.n}"><span class="l ${lc||''}">${esc(r.l)}</span><span class="t"><i style="width:${r.n/mx*100}%"></i></span><span class="v">${r.n}</span></div>`).join('')}
